'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const d = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

(async () => {
  let t = 0; const now = () => t;

  // set wins over older pending load; old load doesn't restart TTL
  { const g = d(); let calls = 0;
    const c = createCache({ now, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'new') });
    const r = c.get('k'); await tick();
    c.set('k', 'S'); t = 5; g.resolve('old');
    assert.equal(await r, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2); t = 0; }

  // set then expire while old load pending -> new load, not detached one
  { const g = d(); let calls = 0;
    const c = createCache({ now, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'fresh') });
    c.get('k'); await tick(); c.set('k', 'S'); t = 10;
    assert.equal(await c.get('k'), 'fresh'); g.resolve('old'); await tick();
    assert.equal(await c.get('k'), 'fresh'); assert.equal(calls, 2); t = 0; }

  // detached flight must not unregister newer flight
  { const g1 = d(), g2 = d(); let calls = 0;
    const c = createCache({ now, load: () => (++calls === 1 ? g1.promise : calls === 2 ? g2.promise : 'x') });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick(); g1.resolve('A'); assert.equal(await a, 'A');
    const b2 = c.get('k'); assert.equal(calls, 2);
    g2.resolve('B'); assert.equal(await b, 'B'); assert.equal(await b2, 'B');
    assert.equal(await c.get('k'), 'B'); }

  // repeated invalidations with no stored value; clear
  { const gs = [d(), d(), d()]; let calls = 0;
    const c = createCache({ now, load: () => gs[calls++].promise });
    c.get('k'); await tick(); c.invalidate('k'); c.get('k'); await tick(); c.invalidate('k');
    const p3 = c.get('k'); await tick(); assert.equal(calls, 3);
    gs[2].resolve(3); gs[0].resolve(1); gs[1].resolve(2); assert.equal(await p3, 3); await tick();
    assert.equal(await c.get('k'), 3);
    c.clear(); assert.equal(c.size, 0); }

  // rejection (async, sync throw, non-Error) not cached, shared, retryable
  { let calls = 0; const reason = { why: 1 };
    const c = createCache({ now, load: () => { calls++; if (calls === 1) throw reason; if (calls === 2) return Promise.reject(7); return 'ok'; } });
    const x = c.get('k'), y = c.get('k');
    await assert.rejects(x, r => r === reason); await assert.rejects(y, r => r === reason);
    await assert.rejects(c.get('k'), r => r === 7);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 3); }

  // rejected detached flight doesn't remove newer flight
  { const g1 = d(), g2 = d(); let calls = 0;
    const c = createCache({ now, load: () => (++calls === 1 ? g1.promise : g2.promise) });
    const a = c.get('k'); await tick(); c.invalidate('k'); c.get('k'); await tick();
    g1.reject(new Error('e')); await assert.rejects(a); c.get('k'); assert.equal(calls, 2);
    g2.resolve('v'); assert.equal(await c.get('k'), 'v'); }

  // ttl 0: dedupes but never reuses
  { let calls = 0; const c = createCache({ now, ttlMs: 0, load: () => ++calls });
    const [a, b] = await Promise.all([c.get('k'), c.get('k')]); assert.equal(a, b);
    assert.equal(await c.get('k'), 2); assert.equal(c.size, 0); }

  // load calls set synchronously on own key: set value wins
  { let c; c = createCache({ now, load: k => { c.set(k, 'S'); return 'L'; } });
    assert.equal(await c.get('k'), 'L'); assert.equal(await c.get('k'), 'S'); }

  // load reads own key without awaiting -> joins its flight
  { let calls = 0, inner; const c = createCache({ now, load: k => { calls++; inner = c.get(k); return 'v'; } });
    assert.equal(await c.get('k'), 'v'); assert.equal(await inner, 'v'); assert.equal(calls, 1); }

  console.log('smoke ok');
})().catch(e => { console.error(e); process.exit(1); });

